private:
    static constexpr uint16_t PHRED_PASS_MASK = 0xaf;     // NC: lowercase a,f
    static constexpr uint16_t N_BASE_MASK = 0x3b;         // NC: lowercase b
    static constexpr uint16_t HIGH_QUALITY = 0xff;        // NC: lowercase f
